import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 100001;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();
        int limit = sc.nextInt();

        if (b <= limit) {
            long g;
            while ((g = gcd(a, b)) > 1) {
                a /= g;
                b /= g;
            }
            System.out.println(a + "/" + b);
            sc.close();
            return;
        }

        double min_difference = 1e9;
        long numerator_result = 0;
        long denominator_result = 1;

        for (int i = 1; i <= limit; i++) {
            long l = lcm(i, b);
            long w = a * (l / b);
            double diff1 = (double) (w - ((w / (l / i)) * (l / i))) / (double) l;
            if (min_difference > diff1) {
                min_difference = diff1;
                numerator_result = (w / (l / i));
                denominator_result = i;
            }
            long num = w + (l / i) - 1;
            long den = (l / i);
            double diff2 = Math.abs(w - ((num / den) * den)) / (double) l;
            if (min_difference > diff2) {
                min_difference = diff2;
                numerator_result = (num / den);
                denominator_result = i;
            }
        }

        long g = gcd(numerator_result, denominator_result);
        numerator_result /= g;
        denominator_result /= g;
        System.out.println(numerator_result + "/" + denominator_result);
        sc.close();
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }
}

